/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.optimize import minimize; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); s=d.SES.to_numpy(); y=d['BA DEGREE COMPLETED'].to_numpy(float); r=d.SAMPLE_RACE; b=r.eq('Black').to_numpy(float); h=r.eq('Hispanic').to_numpy(float); 
for mask in [r.eq('White')|r.eq('Black'), ~r.eq('Hispanic'), np.ones(len(d),bool)]:
 X=np.c_[np.ones(mask.sum()),s[mask],b[mask],s[mask]*b[mask]]; yy=y[mask]; f=lambda z:(np.logaddexp(0,X@z).sum()-yy@(X@z), X.T@(expit(X@z)-yy)); o=minimize(lambda z:f(z)[0],np.zeros(4),jac=lambda z:f(z)[1],method='BFGS'); print(mask.sum(),o.x)
\""

